nasiController::class, 'storePublic']);// Routes lain tetap wajib loginRoute::middleware('auth:sanctum')->group(function (){ Route::get('/logout', [AuthController::class, 'logout']); // Donatur (GET/PUT/DELETE) wajib login Route::get('/donatur', [DonaturController::class, 'index']); Route::get('/donatur/{donatur}', [DonaturController::class, 'show']); Route::put('/donatur/{donatur}', [DonaturController::class, 'update']); Route::delete('/donatur/{donatur}', [DonaturController::class, 'destroy']); // Donasi tetap login (bisa CRUD) Route::apiResource('donasi', DonasiController::class); // LAPORAN Route::get('/laporan', [DonasiController::class, 'laporan']); // Profil user Route::get('/user/profile', [UserController::class, 'profile']); Route::post('/user/profile', [UserController::class, 'updateProfile']); Route::delete('/user/profile/photo', [UserController::class, 'deletePhoto'])});//=====================// ADMIN & PETUGAS MELIHAT SEMUA DONASI (termasuk anonim)//=====================Route::middleware(['auth:sanctum', 'role:admin,petugas'])->group(function (){ Route::get('/donasi', [DonasiController::class, 'index'])});//=====================// LAPORAN PETUGAS//=====================Route::middleware(['auth:sanctum', 'role:petugas'])->group(function (){ Route::get('/petugas/laporan', [DonasiController::class, 'laporanPetugas']); Route::middleware('auth:sanctum')->get('/petugas/laporan-pdf', [DonasiController::class, 'laporanPdf'])});//=====================// LAPORAN PDF//=====================Route::middleware('auth:sanctum')->get('/laporan-pdf', [DonasiController::class, 'laporanPdf']);//=====================// VERIFIKASI DONASI OLEH ADMIN//=====================Route::middleware(['auth:sanctum', 'role:admin'])->group(function (){ Route::put('/donasi/{id}/verifikasi', [DonasiController::class, 'verifikasiAdmin']); //==========================// ROUTE ADMIN DONASI //==========================Route::get('/admin/dashboard', [AdminDonasiController::class, 'dashboard']); Route::get('/admin/donasi', [AdminDonasiController::class, 'index']); Route::post('/admin/donasi/verifikasi', [AdminDonasiController::class, 'updateVerifikasi'])});//=====================// DASHBOARD PETUGAS TAMBAHAN//=====================Route::middleware(['auth:sanctum', 'role:petugas'])->group(function (){ Route::get('/petugas/dashboard-data', [DonasiController::class, 'dashboardPetugas']); Route::get('/petugas/pelacakan', [DonasiController::class, 'pelacakanPetugas'])});Route::middleware('auth:sanctum')->get('/admin/laporan-pdf', [DonasiController::class, 'laporanPdf']);// USER BISA LIHAT DONASI MILIKNYA SENDIRIRoute::middleware(['auth:sanctum', 'role:user'])->group(function (){ Route::get('/donasi/user', [DonasiController::class, 'donasiUser'])});